  forceArrow(vecA, DOTA[0], DOTA[1], U, 66, RED, 'T', '', 10, -8, 'T: tension in the cord');
  forceArrow(vecA, DOTA[0], DOTA[1], fBA, 46, pairC, 'f', 'BA', fBA[0] * 12 - 8, fBA[1] * 12 + 14, 'f_BA: friction exerted by B on A — opposes A\u2019s sliding tendency');
  forceArrow(vecA, DOTA[0], DOTA[1], [0, 1], 56, RED, 'w', 'A', 12, 8, 'w_A: weight of block A');
  // --- panel (b): forces ON B ---
  forceArrow(vecB, DOTB[0], DOTB[1], N, 66, RED, 'N', 'B', -10, -10, 'N_B: normal force exerted by the incline on B');
  forceArrow(vecB, DOTB[0], DOTB[1], rot(fAB, 12), 44, pairC, 'f', 'AB', 14, -14, 'f_AB: friction exerted by A on B — partner of f_BA');
  forceArrow(vecB, DOTB[0], DOTB[1], rot(U, -10), 58, RED, 'f', 'B', 16, 2, 'f_B: friction exerted by the incline on B');
  forceArrow(vecB, DOTB[0], DOTB[1], [-N[0], -N[1]], 46, pairC, 'N', 'AB', 18, 6, 'N_AB: normal force exerted by A on B — partner of N_BA');
  forceArrow(vecB, DOTB[0], DOTB[1], [0, 1], 62, RED, 'w', 'B', -26, 10, 'w_B: weight of block B');
}

/* ---------- legends ---------- */
var legA = draw.group(), legB = draw.group();
legend(legA, 470, 28, 'w', 'A', 'weight of block A');
legend(legA, 470, 62, 'T', '', 'tension');
legend(legA, 470, 96, 'N', 'BA', 'normal force exerted by B on A');
legend(legA, 470, 130, 'f', 'BA', 'friction force exerted by B on A');
legend(legB, 470, 296, 'w', 'B', 'weight of block B');
legend(legB, 470, 330, 'N', 'AB', 'normal force exerted by A on B');
legend(legB, 470, 364, 'N', 'B', 'normal force exerted by the incline plane on B');
legend(legB, 470, 398, 'f', 'AB', 'friction force exerted by A on B');
legend(legB, 470, 432, 'f', 'B', 'friction force exerted by the incline plane on B');

/* ---------- isolation / state application ---------- */
function applyState() {
  var aOn = state.isolate !== 'B', bOn = state.isolate !== 'A';
  var aOp = (state.isolate === 'both' || aOn) ? 1 : DIM;
  var bOp = (state.isolate === 'both' || bOn) ? 1 : DIM;
  if (state.isolate === 'both') { aOp = 1; bOp = 1; }
  if (state.isolate === 'A') { aOp = 1; bOp = DIM; }
  if (state.isolate === 'B') { aOp = DIM; bOp = 1; }
  [fbdA, legA, sketchA.group].forEach(function (g) { g.opacity(aOp); });
  [fbdB, legB, sketchB.group].forEach(function (g) { g.opacity(bOp); });
  sketchA.outA.stroke({ width: 3, color: '#222' });
  sketchA.outB.stroke({ width: 1, color: '#999' });
  sketchB.outA.stroke({ width: 1, color: '#999' });
  sketchB.outB.stroke({ width: 3, color: '#222' });
  renderVectors();
}
function setIsolate(v) { state.isolate = v; applyState(); }
function toggle_thirdLawPairs(on) { state.pairs = on; applyState(); }
function update_slidingTendency(v) { state.tendency = v; applyState(); }

/* ---------- demo step player ---------- */
var steps = [
  { title: 'Isolate block A', narration: 'Click block A: its outline and free-body diagram brighten while B fades. Only four forces act ON A — its weight, the tension, and the normal and friction forces from B.', state: { isolate: 'A', pairs: false, tendency: 'down' } },
  { title: 'Isolate block B', narration: 'Click block B: now five forces appear, including the normal and friction forces that A exerts back on B, plus the contact forces from the incline itself.', state: { isolate: 'B', pairs: false, tendency: 'down' } },
  { title: 'Compare the contact pairs', narration: 'With both diagrams visible, pair highlighting shows N_BA on A and N_AB on B point in opposite directions, as do f_BA and f_AB — third-law partners always live on different bodies.', state: { isolate: 'both', pairs: true, tendency: 'down' } },
  { title: 'Reverse the sliding tendency', narration: 'Switch the tendency to \u2018A tends to slide up\u2019: the friction arrows at the A\u2013B contact flip direction on both diagrams — friction responds to the impending relative motion, not to a fixed direction.', state: { isolate: 'both', pairs: true, tendency: 'up' } }
];
var stepIdx = 0;
function gotoStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  state.isolate = s.state.isolate;
  state.pairs = s.state.pairs;
  state.tendency = s.state.tendency;
  document.getElementById('thirdLawPairsInput').checked = state.pairs;
  document.getElementById('slidingTendencyInput').value = state.tendency;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
  applyState();
}
function nextStep() { gotoStep(stepIdx + 1); }
function prevStep() { gotoStep(stepIdx - 1); }

gotoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

