var TH = 27.6 * Math.PI / 180;
var U = [Math.cos(TH), -Math.sin(TH)];   // up-slope unit (screen coords)
var N = [-Math.sin(TH), -Math.cos(TH)];  // normal, away from incline (up-left)
var RED = '#c02028', ACCENT = '#0b6fa4', DIM = 0.32;

