/* ---------- helpers ---------- */
function rot(v, deg) {
  var a = deg * Math.PI / 180, c = Math.cos(a), s = Math.sin(a);
  return [v[0] * c - v[1] * s, v[0] * s + v[1] * c];
}
function arrowHead(g, tx, ty, dx, dy, color, s) {
  s = s || 5.2;
  var px = -dy, py = dx;
  var bx = tx - dx * 13, by = ty - dy * 13;
  g.polygon([tx, ty, bx + px * s, by + py * s, bx - px * s, by - py * s].join(' ')).fill(color);
}
/* Vector symbol: italic letter + subscript + a DRAWN over-arrow (no combining chars) */
function vecSym(g, x, y, main, sub, fs, tip) {
  fs = fs || 18;
  var grp = g.group();
  var lw = main.length * fs * 0.52;                 // approx letter width
  var subW = sub ? sub.length * fs * 0.42 : 0;
  var tot = lw + subW;
  var tx = grp.text(main).font({ family: 'Times New Roman, serif', size: fs, style: 'italic', weight: 'bold' })
    .fill('#111').move(x - tot / 2, y - fs * 0.62)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  if (sub) {
    grp.text(sub).font({ family: 'Times New Roman, serif', size: fs * 0.66, weight: 'bold' })
      .fill('#111').move(x - tot / 2 + lw, y - fs * 0.30)
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  }
  // drawn over-arrow: short line + tiny head above the letter
  var ay = y - fs * 0.80;
  var ax0 = x - tot / 2 - 1, ax1 = x - tot / 2 + lw + 1;
  grp.line(ax0, ay, ax1, ay).stroke({ color: '#111', width: 1.6 });
  grp.polygon([ax1 + 4.5, ay, ax1 - 1, ay - 2.2, ax1 - 1, ay + 2.2].join(' ')).fill('#111');
  if (tip) {
