// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 940, 560);

var TH = 27.6 * Math.PI / 180;
var U = [Math.cos(TH), -Math.sin(TH)];   // up-slope unit (screen coords)
var N = [-Math.sin(TH), -Math.cos(TH)];  // normal, away from incline (up-left)
var RED = '#c02028', ACCENT = '#0b6fa4', DIM = 0.32;

var state = { isolate: 'A', pairs: false, tendency: 'down' };

/* ---------- helpers ---------- */
function rot(v, deg) {
  var a = deg * Math.PI / 180, c = Math.cos(a), s = Math.sin(a);
  return [v[0] * c - v[1] * s, v[0] * s + v[1] * c];
}
function arrowHead(g, tx, ty, dx, dy, color, s) {
  s = s || 5.2;
  var px = -dy, py = dx;
  var bx = tx - dx * 13, by = ty - dy * 13;
  g.polygon([tx, ty, bx + px * s, by + py * s, bx - px * s, by - py * s].join(' ')).fill(color);
}
/* Vector symbol: italic letter + subscript + a DRAWN over-arrow (no combining chars) */
function vecSym(g, x, y, main, sub, fs, tip) {
  fs = fs || 18;
  var grp = g.group();
  var lw = main.length * fs * 0.52;                 // approx letter width
  var subW = sub ? sub.length * fs * 0.42 : 0;
  var tot = lw + subW;
  var tx = grp.text(main).font({ family: 'Times New Roman, serif', size: fs, style: 'italic', weight: 'bold' })
    .fill('#111').move(x - tot / 2, y - fs * 0.62)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  if (sub) {
    grp.text(sub).font({ family: 'Times New Roman, serif', size: fs * 0.66, weight: 'bold' })
      .fill('#111').move(x - tot / 2 + lw, y - fs * 0.30)
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  }
  // drawn over-arrow: short line + tiny head above the letter
  var ay = y - fs * 0.80;
  var ax0 = x - tot / 2 - 1, ax1 = x - tot / 2 + lw + 1;
  grp.line(ax0, ay, ax1, ay).stroke({ color: '#111', width: 1.6 });
  grp.polygon([ax1 + 4.5, ay, ax1 - 1, ay - 2.2, ax1 - 1, ay + 2.2].join(' ')).fill('#111');
  if (tip) {
    grp.attr('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip);
  }
  return grp;
}
function forceArrow(g, ox, oy, dir, len, color, main, sub, ldx, ldy, tip) {
  var tx = ox + dir[0] * len, ty = oy + dir[1] * len;
  var ln = g.line(ox, oy, tx, ty).stroke({ color: color, width: 3 });
  arrowHead(g, tx, ty, dir[0], dir[1], color);
  vecSym(g, tx + (ldx || 0), ty + (ldy || 0), main, sub, 20, tip);
  ln.attr('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', hideTooltip);
}
/* legend row: drawn vector symbol + plain definition text */
function legend(g, x, y, main, sub, def) {
  vecSym(g, x + 16, y + 10, main, sub, 16);
  g.text(' =  ' + def).font({ family: 'Times New Roman, serif', size: 16 })
    .fill('#111').move(x + 46, y + 2)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
}

/* ---------- incline sketches ---------- */
function sketch(yBase) {
  var g = draw.group();
  var wedge = g.polygon([210, yBase, 445, yBase, 445, yBase - 122].join(' '))
    .fill('#f0d9a8').stroke({ color: '#b99d6b', width: 1.5 });
  g.line(445, yBase - 176, 445, yBase).stroke({ color: '#555', width: 2.5 });
  var bx = 385, by = yBase - 92;
  var bc = [bx + N[0] * 20, by + N[1] * 20];
  var ac = [bx + N[0] * 50, by + N[1] * 50];
  var deg = -27.6;
  var blocks = g.group().rotate(deg, bx, by);
  var rectB = blocks.rect(62, 38).center(bc[0], bc[1]).fill('#d9b380').stroke({ color: '#8a6d3b', width: 1.5 });
  var rectA = blocks.rect(38, 26).center(ac[0], ac[1]).fill('#f4a582').stroke({ color: '#a85b3a', width: 1.5 });
  blocks.plain('B').font({ family: 'sans-serif', size: 15 }).center(bc[0], bc[1]);
  blocks.plain('A').font({ family: 'sans-serif', size: 13 }).center(ac[0], ac[1]);
  g.line(ac[0] + U[0] * 17, ac[1] + U[1] * 17, 445, yBase - 120).stroke({ color: '#111', width: 1.6 });
  var outA = blocks.rect(52, 38).center(ac[0], ac[1]).radius(10).fill('none')
    .stroke({ color: '#555', width: 2 });
  var outB = blocks.rect(76, 50).center(bc[0], bc[1]).radius(12).fill('none')
    .stroke({ color: '#555', width: 2 });
  rectA.attr('cursor', 'pointer').on('click', function () { setIsolate('A'); });
  rectB.attr('cursor', 'pointer').on('click', function () { setIsolate('B'); });
  rectA.on('mousemove', function (e) { showTooltip('Block A — click to isolate it', e); }).on('mouseleave', hideTooltip);
  rectB.on('mousemove', function (e) { showTooltip('Block B — click to isolate it', e); }).on('mouseleave', hideTooltip);
  wedge.attr('cursor', 'pointer').on('click', function () { setIsolate('both'); })
    .on('mousemove', function (e) { showTooltip('Click to show both bodies', e); }).on('mouseleave', hideTooltip);
  return { group: g, outA: outA, outB: outB };
}
var sketchA = sketch(240);
var sketchB = sketch(520);
draw.plain('(a)').font({ family: 'sans-serif', size: 16 }).move(462, 252);
draw.plain('(b)').font({ family: 'sans-serif', size: 16 }).move(462, 534);

/* ---------- free-body diagrams ---------- */
var fbdA = draw.group(), fbdB = draw.group();
var vecA = fbdA.group(), vecB = fbdB.group();
var DOTA = [118, 126], DOTB = [118, 404];

function dashedSlope(g, dot) {
  g.line(dot[0] - U[0] * 100, dot[1] - U[1] * 100, dot[0] + U[0] * 66, dot[1] + U[1] * 66)
    .stroke({ color: '#333', width: 1.5, dasharray: '6,5' });
  g.circle(10).center(dot[0], dot[1]).fill('#000');
}
dashedSlope(fbdA, DOTA);
dashedSlope(fbdB, DOTB);
vecA.front(); vecB.front();

function renderVectors() {
  vecA.clear(); vecB.clear();
  var pairC = state.pairs ? ACCENT : RED;
  var upTend = state.tendency === 'up';
  var fBA = upTend ? [-U[0], -U[1]] : U;   // friction on A by B opposes A's tendency
  var fAB = [-fBA[0], -fBA[1]];            // third-law partner on B
  /* --- panel (a): forces ON A --- */
  forceArrow(vecA, DOTA[0], DOTA[1], N, 68, pairC, 'N', 'BA', -8, -12, 'N_BA: normal force exerted by B on A');
  forceArrow(vecA, DOTA[0], DOTA[1], U, 72, RED, 'T', '', 14, -8, 'T: tension in the cord');
  forceArrow(vecA, DOTA[0], DOTA[1], fBA, 50, pairC, 'f', 'BA', fBA[0] * 14 - 10, fBA[1] * 14 + 16, 'f_BA: friction exerted by B on A — opposes A\u2019s sliding tendency');
  forceArrow(vecA, DOTA[0], DOTA[1], [0, 1], 60, RED, 'w', 'A', 16, 10, 'w_A: weight of block A');
  /* --- panel (b): forces ON B — wide angular separation to avoid crowding --- */
  forceArrow(vecB, DOTB[0], DOTB[1], N, 72, RED, 'N', 'B', -14, -12, 'N_B: normal force exerted by the incline on B');
  forceArrow(vecB, DOTB[0], DOTB[1], rot(fAB, 26), 48, pairC, 'f', 'AB', 8, -18, 'f_AB: friction exerted by A on B — partner of f_BA');
  forceArrow(vecB, DOTB[0], DOTB[1], rot(U, -22), 60, RED, 'f', 'B', 20, 10, 'f_B: friction exerted by the incline on B');
  forceArrow(vecB, DOTB[0], DOTB[1], rot([-N[0], -N[1]], -18), 50, pairC, 'N', 'AB', 22, 12, 'N_AB: normal force exerted by A on B — partner of N_BA');
  forceArrow(vecB, DOTB[0], DOTB[1], [0, 1], 66, RED, 'w', 'B', -30, 14, 'w_B: weight of block B');
}

/* ---------- legends ---------- */
var legA = draw.group(), legB = draw.group();
legend(legA, 500, 26, 'w', 'A', 'weight of block A');
legend(legA, 500, 62, 'T', '', 'tension');
legend(legA, 500, 98, 'N', 'BA', 'normal force exerted by B on A');
legend(legA, 500, 134, 'f', 'BA', 'friction force exerted by B on A');
legend(legB, 500, 306, 'w', 'B', 'weight of block B');
legend(legB, 500, 342, 'N', 'AB', 'normal force exerted by A on B');
legend(legB, 500, 378, 'N', 'B', 'normal force exerted by the incline plane on B');
legend(legB, 500, 414, 'f', 'AB', 'friction force exerted by A on B');
legend(legB, 500, 450, 'f', 'B', 'friction force exerted by the incline plane on B');

/* ---------- isolation / state application ---------- */
function applyState() {
  var aOp = 1, bOp = 1;
  if (state.isolate === 'A') { aOp = 1; bOp = DIM; }
  else if (state.isolate === 'B') { aOp = DIM; bOp = 1; }
  [fbdA, legA, sketchA.group].forEach(function (g) { g.opacity(aOp); });
  [fbdB, legB, sketchB.group].forEach(function (g) { g.opacity(bOp); });
  sketchA.outA.stroke({ width: 3, color: '#222' });
  sketchA.outB.stroke({ width: 1, color: '#999' });
  sketchB.outA.stroke({ width: 1, color: '#999' });
  sketchB.outB.stroke({ width: 3, color: '#222' });
  renderVectors();
}
function setIsolate(v) { state.isolate = v; applyState(); }
function toggle_thirdLawPairs(on) { state.pairs = on; applyState(); }
function update_slidingTendency(v) { state.tendency = v; applyState(); }

/* ---------- demo step player ---------- */
var steps = [
  { narration: 'Click block A: its outline and free-body diagram brighten while B fades. Only four forces act ON A — its weight, the tension, and the normal and friction forces from B.', state: { isolate: 'A', pairs: false, tendency: 'down' } },
  { narration: 'Click block B: now five forces appear, including the normal and friction forces that A exerts back on B, plus the contact forces from the incline itself.', state: { isolate: 'B', pairs: false, tendency: 'down' } },
  { narration: 'With both diagrams visible, pair highlighting shows N_BA on A and N_AB on B point in opposite directions, as do f_BA and f_AB — third-law partners always live on different bodies.', state: { isolate: 'both', pairs: true, tendency: 'down' } },
  { narration: 'Switch the tendency to \u2018A tends to slide up\u2019: the friction arrows at the A\u2013B contact flip direction on both diagrams — friction responds to the impending relative motion, not to a fixed direction.', state: { isolate: 'both', pairs: true, tendency: 'up' } }
];
var stepIdx = 0;
function gotoStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  state.isolate = s.state.isolate;
  state.pairs = s.state.pairs;
  state.tendency = s.state.tendency;
  document.getElementById('thirdLawPairsInput').checked = state.pairs;
  document.getElementById('slidingTendencyInput').value = state.tendency;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
  applyState();
}
function nextStep() { gotoStep(stepIdx + 1); }
function prevStep() { gotoStep(stepIdx - 1); }

gotoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

