  var ac = [bx + N[0] * 50, by + N[1] * 50];
  var deg = -27.6;
  var blocks = g.group().rotate(deg, bx, by);
  var rectB = blocks.rect(62, 38).center(bc[0], bc[1]).fill('#d9b380').stroke({ color: '#8a6d3b', width: 1.5 });
  var rectA = blocks.rect(38, 26).center(ac[0], ac[1]).fill('#f4a582').stroke({ color: '#a85b3a', width: 1.5 });
  blocks.plain('B').font({ family: 'sans-serif', size: 15 }).center(bc[0], bc[1]);
  blocks.plain('A').font({ family: 'sans-serif', size: 13 }).center(ac[0], ac[1]);
  g.line(ac[0] + U[0] * 17, ac[1] + U[1] * 17, 445, yBase - 120).stroke({ color: '#111', width: 1.6 });
  var outA = blocks.rect(52, 38).center(ac[0], ac[1]).radius(10).fill('none')
    .stroke({ color: '#555', width: 2 });
  var outB = blocks.rect(76, 50).center(bc[0], bc[1]).radius(12).fill('none')
    .stroke({ color: '#555', width: 2 });
  rectA.attr('cursor', 'pointer').on('click', function () { setIsolate('A'); });
