  forceArrow(vecA, DOTA[0], DOTA[1], fBA, 50, pairC, 'f', 'BA', fBA[0] * 14 - 10, fBA[1] * 14 + 16, 'f_BA: friction exerted by B on A — opposes A\u2019s sliding tendency');
  forceArrow(vecA, DOTA[0], DOTA[1], [0, 1], 60, RED, 'w', 'A', 16, 10, 'w_A: weight of block A');
